import java.util.Scanner;

public class Main {
    static int n, m, mod;
    static int[] g = new int[505], sg = new int[505];
    static int[][] f = new int[505][505], sf = new int[505][505];
    static int[][] C = new int[505][505];

    static void computeBinom() {
        C[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = add(C[i - 1][j], C[i - 1][j - 1]);
            }
        }
    }

    static int add(int a, int b) {
        int res = a + b;
        if (res >= mod) res -= mod;
        return res;
    }

    static int sub(int a, int b) {
        int res = a - b;
        if (res < 0) res += mod;
        return res;
    }

    static int sumSeries(int x) {
        long val = (long) x * (x + 1) / 2;
        return (int) (val % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();
        computeBinom();

        g[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long tmp = (long) g[j - 1] * g[i - j] % mod * C[i - 1][j - 1] % mod;
                g[i] = (int) ((g[i] + tmp * (i + 1)) % mod);
                sg[i] = (int) ((sg[i] + (long) sg[j - 1] * g[i - j] % mod * C[i - 1][j - 1] % mod * (i + 1)) % mod);
                sg[i] = (int) ((sg[i] + (long) sg[i - j] * g[j - 1] % mod * C[i - 1][j - 1] % mod * (i + 1)) % mod);
                long sumVal = (sumSeries(i - j) + sumSeries(j - 1)) % mod;
                sg[i] = (int) ((sg[i] + tmp * sumVal) % mod);
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                f[i][j] = 0;
                sf[i][j] = 0;
            }
        }

        for (int i = 0; i <= n; i++) {
            f[i][0] = 1;
        }

        for (int i = 1; i <= n; i++) {
            if (i <= m) {
                f[i][i] = g[i];
                sf[i][i] = sg[i];
            }
            int limit = Math.min(i - 1, m);
            for (int j = 1; j <= limit; j++) {
                for (int t = i; t >= 1; t--) {
                    if (i - t > j) break;
                    long tmp = (long) g[i - t] * C[j][i - t] % mod;
                    f[i][j] = (int) ((f[i][j] + (long) f[t - 1][j - i + t] * tmp) % mod);
                    sf[i][j] = (int) ((sf[i][j] + (long) sf[t - 1][j - i + t] * tmp) % mod);
                    long addVal = (long) f[t - 1][j - i + t] * sg[i - t] % mod * C[j][i - t] % mod;
                    sf[i][j] = (int) ((sf[i][j] + addVal) % mod);
                }
            }
        }

        System.out.println(sf[n][m]);
        sc.close();
    }
}
